  async createNode(workspaceId:string,input:{name:string;provider:string;credential?:string|undefined},key:Buffer){return this.tx(async c=>{let credentialId:null|string=null;if(input.credential){credentialId=randomUUID();const e=encryptSecret(input.credential,key);await c.query("INSERT INTO credentials(id,workspace_id,name,algorithm,iv,tag,ciphertext) VALUES($1,$2,$3,$4,$5,$6,$7)",[credentialId,workspaceId,`node:${input.name}`,e.algorithm,e.iv,e.tag,e.ciphertext])}const id=randomUUID();const r=await c.query("INSERT INTO nodes(id,workspace_id,name,provider,credential_id) VALUES($1,$2,$3,$4,$5) RETURNING id,name,provider,credential_id IS NOT NULL configured,created_at",[id,workspaceId,input.name,input.provider,credentialId]);return r.rows[0]})}
  async deleteNode(workspaceId:string,id:string){const r=await this.pool.query("UPDATE nodes SET revoked_at=now() WHERE id=$1 AND workspace_id=$2 AND revoked_at IS NULL",[id,workspaceId]);if(!r.rowCount)throw new DatabaseError("not_found")}
  async createEnrollment(workspaceId:string,tokenHash:string,expiresAt:Date,input:{name?:string;labels?:Record<string,string>;metadata?:Record<string,unknown>}={}){const id=randomUUID();await this.pool.query("INSERT INTO enrollment_tokens(id,workspace_id,token_hash,expires_at,name,labels,metadata) VALUES($1,$2,$3,$4,$5,$6,$7)",[id,workspaceId,tokenHash,expiresAt,input.name??"agent",input.labels??{},input.metadata??{}]);return{id,expiresAt:expiresAt.toISOString(),name:input.name??"agent",labels:input.labels??{}}}
  async enrollNode(input:{tokenHash:string;provider:string;agentVersion?:string;nodeSecretHash:string;nodeSecret:string}):Promise<NodeCredential>{return this.tx(async c=>{const token=(await c.query("SELECT * FROM enrollment_tokens WHERE token_hash=$1 FOR UPDATE",[input.tokenHash])).rows[0];if(!token||token.revoked_at||token.used_at||new Date(token.expires_at).getTime()<=Date.now())throw new DatabaseError("conflict","enrollment token is invalid");const nodeId=randomUUID();await c.query("INSERT INTO nodes(id,workspace_id,name,provider,credential_hash,enrollment_token_id,labels,agent_version) VALUES($1,$2,$3,$4,$5,$6,$7,$8)",[nodeId,token.workspace_id,token.name,input.provider,input.nodeSecretHash,token.id,token.labels,input.agentVersion??null]);await c.query("UPDATE enrollment_tokens SET used_at=now() WHERE id=$1",[token.id]);return{nodeId,workspaceId:token.workspace_id,nodeSecret:input.nodeSecret}})}
  async authenticateNode(secretHash:string):Promise<AuthenticatedNode|null>{const r=await this.pool.query("SELECT id,workspace_id,name,connection_epoch FROM nodes WHERE credential_hash=$1 AND revoked_at IS NULL",[secretHash]);const x=r.rows[0];return x?{id:x.id,workspaceId:x.workspace_id,name:x.name,connectionEpoch:Number(x.connection_epoch)}:null}
  async heartbeat(nodeId:string,input:{sessionId:string;observedAt:string;runtimes:{endpointId:string;generation:number;runtime:string;provider:string;protocol:string;convergence:string;metadata?:Record<string,unknown>|undefined}[]}){return this.tx(async c=>{const node=(await c.query("SELECT workspace_id,connection_epoch,connection_session_id,last_heartbeat_at FROM nodes WHERE id=$1 AND revoked_at IS NULL FOR UPDATE",[nodeId])).rows[0];if(!node)throw new DatabaseError("unauthorized");const same=node.connection_session_id===input.sessionId;if(!same&&node.connection_session_id){if((await c.query("SELECT 1 FROM retired_node_sessions WHERE node_id=$1 AND session_id=$2",[nodeId,input.sessionId])).rowCount)throw new DatabaseError("conflict","retired session rejected");if(node.last_heartbeat_at&&(await c.query("SELECT $1::timestamptz > now()-make_interval(secs => $2)",[node.last_heartbeat_at,nodeFreshMs/1000])).rows[0]["?column?"])throw new DatabaseError("conflict","active session owns node");await c.query("INSERT INTO retired_node_sessions(node_id,session_id) VALUES($1,$2) ON CONFLICT DO NOTHING",[nodeId,node.connection_session_id]);const reason={reason:"session_takeover",retiredSessionId:node.connection_session_id};await c.query("UPDATE agent_commands SET status='stale',result_at=coalesce(result_at,now()),result=$3,updated_at=now() WHERE node_id=$1 AND connection_epoch=$2 AND status IN ('queued','leased')",[nodeId,node.connection_epoch,reason]);await c.query("UPDATE operations SET status='failed',result=$3,updated_at=now() WHERE node_id=$1 AND connection_epoch=$2 AND status IN ('queued','running')",[nodeId,node.connection_epoch,reason])}const epoch=Number(node.connection_epoch)+(same?0:1);await c.query("UPDATE nodes SET last_heartbeat_at=now(),connection_epoch=$2,connection_session_id=$3,heartbeat_metadata=$4,updated_at=now() WHERE id=$1",[nodeId,epoch,input.sessionId,{observedAt:input.observedAt,runtimes:input.runtimes.length}]);for(const runtime of input.runtimes){await c.query("INSERT INTO observations(id,workspace_id,endpoint_id,generation,state) SELECT $1,workspace_id,id,$3,$4 FROM endpoints WHERE id=$2 AND node_id=$5 AND workspace_id=$6",[randomUUID(),runtime.endpointId,runtime.generation,{node:"online",runtime:runtime.runtime,provider:runtime.provider,protocol:runtime.protocol,convergence:runtime.convergence,metadata:runtime.metadata??{}},nodeId,node.workspace_id])}return{connectionEpoch:epoch}})}
  async endpoints(workspaceId:string){return (await this.pool.query(`SELECT e.*,n.name node_name,n.last_heartbeat_at node_last_heartbeat_at,o.state observation_state,o.generation observation_generation,a.id active_operation_id FROM endpoints e LEFT JOIN nodes n ON n.id=e.node_id LEFT JOIN LATERAL (SELECT state,generation FROM observations WHERE endpoint_id=e.id ORDER BY created_at DESC LIMIT 1) o ON true LEFT JOIN LATERAL (SELECT id FROM operations WHERE endpoint_id=e.id AND status IN ('queued','running') ORDER BY created_at LIMIT 1) a ON true WHERE e.workspace_id=$1 ORDER BY e.created_at`,[workspaceId])).rows.map(mapEndpoint)}
