  async createEndpoint(workspaceId:string,name:string,providerId:string,nodeId?:string,configuration:Record<string,unknown>={}){const id=randomUUID(),config=Object.keys(configuration).length?configuration:providerId==="napcat"?{qq:{}}:{};await this.tx(async c=>{if(nodeId){const node=(await c.query("SELECT provider FROM nodes WHERE workspace_id=$1 AND id=$2 AND revoked_at IS NULL FOR UPDATE",[workspaceId,nodeId])).rows[0];if(!node)throw new DatabaseError("not_found");if(node.provider!==providerId)throw new DatabaseError("conflict","endpoint provider must match node provider")}await c.query("INSERT INTO endpoints(id,workspace_id,node_id,name,provider_id,configuration) VALUES($1,$2,$3,$4,$5,$6)",[id,workspaceId,nodeId??null,name,providerId,config])});return (await this.endpoint(workspaceId,id))!}
  async updateEndpoint(workspaceId:string,id:string,name:string){const r=await this.pool.query("UPDATE endpoints SET name=$3,updated_at=now() WHERE workspace_id=$1 AND id=$2 RETURNING id",[workspaceId,id,name]);if(!r.rows[0])throw new DatabaseError("not_found");return (await this.endpoint(workspaceId,id))!}
  async deleteEndpoint(workspaceId:string,id:string){await this.tx(async c=>{const params=[workspaceId,id];await c.query("DELETE FROM observations WHERE workspace_id=$1 AND endpoint_id=$2",params);await c.query("DELETE FROM agent_commands WHERE workspace_id=$1 AND endpoint_id=$2",params);await c.query("DELETE FROM outbox_events WHERE operation_id IN (SELECT id FROM operations WHERE workspace_id=$1 AND endpoint_id=$2)",params);await c.query("DELETE FROM operations WHERE workspace_id=$1 AND endpoint_id=$2",params);const r=await c.query("DELETE FROM endpoints WHERE workspace_id=$1 AND id=$2",params);if(!r.rowCount)throw new DatabaseError("not_found")})}
  async mutateEndpoint(input:{workspaceId:string;endpointId:string;actorUserId:string;action:Action;expectedGeneration:number;idempotencyKey:string;metadata?:Record<string,unknown>}){return this.tx(async c=>{const requestHash=digest(JSON.stringify({action:input.action,expectedGeneration:input.expectedGeneration,metadata:input.metadata??{}}));const previous=await c.query("SELECT * FROM operations WHERE workspace_id=$1 AND endpoint_id=$2 AND idempotency_key=$3",[input.workspaceId,input.endpointId,input.idempotencyKey]);if(previous.rows[0]){if(previous.rows[0].request_hash!==requestHash)throw new DatabaseError("idempotency_mismatch");return{operation:mapOperation(previous.rows[0]),replayed:true}}const er=await c.query("SELECT * FROM endpoints WHERE workspace_id=$1 AND id=$2 FOR UPDATE",[input.workspaceId,input.endpointId]);const ep=er.rows[0];if(!ep)throw new DatabaseError("not_found");if(input.action==="refresh-login-qr"&&ep.provider_id!=="napcat")throw new DatabaseError("conflict","QR refresh requires a NapCat endpoint");if(Number(ep.generation)!==input.expectedGeneration)throw new DatabaseError("conflict","generation conflict");const active=await c.query("SELECT 1 FROM operations WHERE endpoint_id=$1 AND status IN ('queued','running')",[ep.id]);if(active.rowCount)throw new DatabaseError("conflict","operation conflict");const readOnly=input.action==="refresh-login-qr"||input.action==="read-container-logs"||input.action==="update-onebot-websockets",generation=Number(ep.generation)+(readOnly?0:1),desired=readOnly?ep.desired_state:{state:input.action==="stop"?"stopped":"running"};const configuration=input.action==="update-onebot-websockets"?{...((ep.configuration as Record<string,unknown>)??{}),onebotWebsockets:{websocketClients:input.metadata?.websocketClients??[],websocketServers:input.metadata?.websocketServers??[]}}:ep.configuration;await c.query("UPDATE endpoints SET generation=$3,desired_state=$4,configuration=$5,updated_at=now() WHERE workspace_id=$1 AND id=$2",[input.workspaceId,input.endpointId,generation,desired,configuration]);const id=randomUUID();const op=(await c.query("INSERT INTO operations(id,workspace_id,endpoint_id,generation,action,idempotency_key,request_hash,status,desired_state) VALUES($1,$2,$3,$4,$5,$6,$7,'queued',$8) RETURNING *",[id,input.workspaceId,input.endpointId,generation,input.action,input.idempotencyKey,requestHash,desired])).rows[0];await c.query("UPDATE operations SET metadata=$2 WHERE id=$1",[id,input.metadata??{}]);op.metadata=input.metadata??{};await c.query("INSERT INTO audit_events(id,workspace_id,actor_user_id,action,resource_type,resource_id,metadata) VALUES($1,$2,$3,'operation.queued','operation',$4,$5)",[randomUUID(),input.workspaceId,input.actorUserId,id,{action:input.action,generation,...(input.metadata??{})}]);await c.query("INSERT INTO outbox_events(id,workspace_id,operation_id,event_type,payload) VALUES($1,$2,$3,'operation.queued',$4)",[randomUUID(),input.workspaceId,id,{operationId:id}]);return{operation:mapOperation(op),replayed:false}})}
  async operations(workspaceId:string){return (await this.pool.query("SELECT * FROM operations WHERE workspace_id=$1 ORDER BY created_at DESC",[workspaceId])).rows.map(mapOperation)}
