export class InMemoryDatabase { workspaces:{id:string;name:string}[]=[]; endpoints:Endpoint[]=[]; operations:Operation[]=[]; audits:{id:string;workspaceId:string;action:string;operationId?:string;createdAt:string}[]=[]; outbox:{id:string;workspaceId:string;operationId:string;processedAt:null|string}[]=[]; observations:{id:string;workspaceId:string;endpointId:string;operationId:string;generation:number;state:string;createdAt:string}[]=[];createWorkspace(name:string){const x={id:randomUUID(),name};this.workspaces.push(x);return x}createEndpoint(workspaceId:string,name:string){if(!this.workspaces.some(x=>x.id===workspaceId))throw new Error("not found");const x:Endpoint={id:randomUUID(),workspaceId,name,providerId:"fake",node:null,generation:0,desired:{state:"stopped"},status:{node:"unassigned",runtime:"unknown",provider:"unknown",protocol:"unknown",convergence:"reconciling"},activeOperationId:null};this.endpoints.push(x);return x}mutateEndpoint(input:{workspaceId:string;endpointId:string;action:Action;expectedGeneration:number;idempotencyKey:string}){const replay=this.operations.find(x=>x.workspaceId===input.workspaceId&&x.endpointId===input.endpointId&&x.idempotencyKey===input.idempotencyKey);if(replay)return{operation:replay,replayed:true};const ep=this.endpoints.find(x=>x.id===input.endpointId&&x.workspaceId===input.workspaceId);if(!ep)throw new Error("not found");if(ep.generation!==input.expectedGeneration)throw new Error("generation conflict");if(this.operations.some(x=>x.endpointId===ep.id&&(x.status==="queued"||x.status==="running")))throw new Error("operation conflict");ep.generation++;ep.desired={state:input.action==="stop"?"stopped":"running"};const operation:Operation={id:randomUUID(),workspaceId:input.workspaceId,endpointId:ep.id,generation:ep.generation,action:input.action,idempotencyKey:input.idempotencyKey,status:"queued",attempts:0,result:null,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),claimedAt:null};this.operations.push(operation);this.audits.push({id:randomUUID(),workspaceId:input.workspaceId,action:"operation.queued",operationId:operation.id,createdAt:new Date().toISOString()});this.outbox.push({id:randomUUID(),workspaceId:input.workspaceId,operationId:operation.id,processedAt:null});return{operation,replayed:false}}}
